  const s1 = (((s0 % 150) + 150) % 150); // st phased
  const s2 = tbxEase_ease_in_out_sine(((75 - Math.abs((s1 - 75))) / 75), 1); // st eased
  const s3 = (0.5 + (((s2 - 0.5) * 1) * 1)); // st (scene-time)
